package com.gmail.manhle240406.project.adoption;
import org.junit.Test;import static org.junit.Assert.*;
import java.time.*;import java.util.*;import com.gmail.manhle240406.project.pet.PetSchema;
public class SafetyContractsTest {
 @Test public void ninetyElapsedDaysAreNotThreeCalendarMonths(){long start=Instant.parse("2026-10-14T10:00:00Z").toEpochMilli();assertEquals(90L*86400000,FollowupTiming.due(start,90)-start);assertNotEquals(Instant.ofEpochMilli(FollowupTiming.due(start,90)),Instant.parse("2026-10-14T10:00:00Z").atZone(ZoneOffset.UTC).plusMonths(3).toInstant());assertThrows(IllegalArgumentException.class,()->FollowupTiming.due(start,8));}
 @Test public void presentationTimezoneDoesNotShiftUtcDeadline(){long start=Instant.parse("2026-10-31T10:00:00Z").toEpochMilli();assertEquals(86400000L,FollowupTiming.due(start,1)-start);assertEquals(Instant.ofEpochMilli(start+86400000),Instant.ofEpochMilli(FollowupTiming.due(start,1)).atZone(ZoneId.of("America/New_York")).toInstant());}
 @Test public void receivedAndEvidenceConcernsDoNotBecomeOverdueOrGuilt(){assertEquals("received",FollowupTiming.state(100,Long.MAX_VALUE,101L));assertEquals("within_grace",FollowupTiming.state(100,100+FollowupTiming.GRACE,null));assertEquals("overdue_needs_review",FollowupTiming.state(100,101+FollowupTiming.GRACE,null));}
 @Test public void fourteenDayExtensionKeepsOriginalBound(){FollowupTiming.extension(100,100+FollowupTiming.EXTENSION,0);assertThrows(IllegalArgumentException.class,()->FollowupTiming.extension(100,101+FollowupTiming.EXTENSION,0));assertThrows(IllegalArgumentException.class,()->FollowupTiming.extension(100,100,100));}
 @Test public void blindRevealAndCommonWindowStopEditing(){assertTrue(FollowupTiming.editReview(0,14*FollowupTiming.DAY,1,false));assertFalse(FollowupTiming.editReview(0,14*FollowupTiming.DAY,1,true));assertFalse(FollowupTiming.editReview(0,14*FollowupTiming.DAY,48L*3600000,false));}
 @Test public void missingCriteriaAreNotZeroRatingsAndEmptySubmissionRejects(){Map<String,Object> input=PetSchema.map("communication",null,"preparation",null,"disclosureAccuracy",null,"comment","");assertThrows(IllegalArgumentException.class,()->ExperienceReviewContract.validate(input));input.put("comment","Factual experience, criteria N/A");ExperienceReviewContract.validate(input);input.put("communication",0L);assertThrows(IllegalArgumentException.class,()->ExperienceReviewContract.validate(input));}
 @Test public void clientKeepsUnknownCareAndMax20WithoutCertifyingMedicalTruth(){Map<String,Object> care=PetCareContract.unknown();assertEquals("unknown",care.get("healthState"));care.put("verified",true);assertThrows(IllegalArgumentException.class,()->PetCareContract.validate(care,"",LocalDate.of(2026,10,14)));}
}
